const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'src', 'data', 'lessons');

// Shooter voice: Carmack — performance-focused, systems-level
const lessons = [
  // L06-L15: Early lessons (all need BT, EI, ST)
  { file: 'lesson-shooter-06-bullet-array.ts',
    bt: '**Using a separate array for each bullet property (x, y, active) without keeping them in sync.** If you add a bullet to the x array but forget the active array, the arrays drift out of alignment. Always update all parallel arrays in the same function.',
    ei: 'Every bullet-hell game from Ikaruga to Touhou stores bullets in flat arrays. The array is the natural data structure for hundreds of identical entities — no pointers, no inheritance, just data and indices.',
    st: 'The RPG stores enemies in parallel arrays the same way — position[], hp[], active[]. The Platformer stores coins in arrays. Parallel arrays for homogeneous entities are the universal pattern across all game architectures.' },
  { file: 'lesson-shooter-07-enemy-array.ts',
    bt: '**Spawning enemies at random positions without checking for overlap.** Two enemies at the same position look like one enemy with double HP. Check that each spawn position is far enough from existing enemies before placing.',
    ei: 'Formation spawning — placing enemies in grids, V-shapes, or circles — dates back to Space Invaders. The spawn pattern is data (positions), not code (random). Your formation loop follows the same data-driven spawn approach.',
    st: 'The RPG places enemies at grid positions from room data. The Crawler places enemies from spawn budgets. All paths spawn entities from data — the coordinate system changes, but the "iterate positions, create entities" pattern is identical.' },
  { file: 'lesson-shooter-08-collision-v0.ts',
    bt: '**Checking collision after moving both the bullet and enemy, then using the old positions for rendering.** Always resolve collision with the current positions, not the pre-move positions. Move, collide, render — in that order.',
    ei: 'AABB overlap (Axis-Aligned Bounding Box) is the fastest 2D collision test: four comparisons, no square roots. Every 2D game engine uses AABB as the broadphase check before more expensive narrow-phase tests.',
    st: 'The RPG checks grid adjacency for combat. The Platformer checks tile overlap for collision. Your AABB overlap test is the continuous-space version — same "do these rectangles overlap?" question, but with floating-point coordinates.' },
  { file: 'lesson-shooter-09-score-counter.ts',
    bt: '**Incrementing the score inside the collision loop without guarding against double-counting.** If a bullet overlaps two enemies in the same frame, you might count one kill as two. Deactivate the bullet after the first hit to prevent double scoring.',
    ei: 'Game state variables like score, lives, and wave number are "observable state" — the HUD reads them every frame. Keeping all observable state in one place (the World struct) makes HUD rendering a pure read operation.',
    st: 'The RPG tracks kills, gold, and XP as observable state. The Crawler tracks floor depth and keys. Every game needs a small set of player-facing counters — the HUD pattern is universal.' },
  { file: 'lesson-shooter-10-micro-shooter.ts',
    bt: '**Adding features before the core loop (shoot, hit, score, respawn) works perfectly.** A wave spawner does not fix a broken collision system. Verify the minimal game loop end-to-end before adding complexity.',
    ei: 'Asteroids shipped as a complete game with one ship, rocks, and bullets. Galaga added waves. Gradius added powerups. Every successful shooter starts with a working core loop and layers features on top.',
    st: 'Every path hits this milestone — RPG L10, Platformer L10, Crawler L10. The core loop test is universal: prove the minimal viable game works before building on it. The genre changes, the milestone principle does not.' },
  { file: 'lesson-shooter-11-component-structs-v0.ts',
    bt: '**Adding methods to component structs.** Components should be plain data (POD types) — no constructors, no methods, no inheritance. Behavior belongs in systems, not in data. If your Position struct has a move() method, you have mixed data and logic.',
    ei: 'Every ECS framework enforces "components are data, systems are behavior." EnTT, flecs, and Unity DOTS all use plain structs for components. Methods on components create hidden dependencies between data and logic.',
    st: 'The RPG uses plain structs for entities too — no methods, just fields. The Crawler stores entities as position + sprite data. POD component structs are the foundation of data-oriented design across all game architectures.' },
  { file: 'lesson-shooter-12-world-state-struct.ts',
    bt: '**Storing game state in global variables.** Globals hide dependencies — any function can read or write any state at any time. A single World struct makes every dependency explicit: functions that take World& declare what they touch.',
    ei: 'Carmack advocated for "functional-style" game code where each system takes the world state as input and produces a new state. A single state root makes this practical — the entire game state lives in one place.',
    st: 'The RPG wraps all game state in a WorldState struct. The Platformer uses a GameState struct. The Crawler uses a DungeonState struct. Every path converges on the same pattern: one struct owns all gameplay data.' },
  { file: 'lesson-shooter-13-entity-ids-v0.ts',
    bt: '**Using array index as an entity reference.** When entity at index 5 is removed and index 6 shifts down to index 5, every reference to "entity 6" now points to entity 5. Use stable integer IDs that never change for a given entity.',
    ei: 'Unity ECS uses generation counters with entity IDs — each reused slot increments a version number. If your stored version does not match the current slot version, the reference is stale. Your integer ID system is the simplified foundation.',
    st: 'The RPG (L13) and Crawler (L32) solve the same identity problem. Stable entity IDs are the prerequisite for any system that stores references — save/load, combat targeting, AI behavior all require entities to have persistent identities.' },
  { file: 'lesson-shooter-14-soa-formalization.ts',
    bt: '**Iterating through all components when you only need positions.** If Position, Velocity, HP, and Color are in one struct, loading one entity loads all four fields into cache. SoA keeps Position[] contiguous — iterating positions never touches HP data.',
    ei: 'Mike Acton (Insomniac Games) demonstrated that SoA layouts can be 10-100x faster than AoS for batch processing. Cache efficiency is the single biggest performance factor in entity-heavy games. Your formalization makes this explicit.',
    st: 'The RPG (L14) formalizes SoA for dungeon entities. The Crawler stores entities as parallel arrays. All paths discover that memory layout determines iteration speed — the same data, reorganized, runs dramatically faster.' },
  { file: 'lesson-shooter-15-data-layout-milestone.ts',
    bt: '**Treating the data layout milestone as "just refactoring."** This milestone changes how your brain thinks about game data. Every future system reads SoA arrays by index. If the layout is wrong here, every future lesson builds on a broken foundation.',
    ei: 'Data-driven rendering — where the render system iterates component arrays instead of entity objects — is how professional engines achieve draw-call batching. Your Color component array enables this: sort by color, batch draws.',
    st: 'RPG L15 and Platformer L15 hit the same data layout milestone. The foundation is identical: stable update order, SoA components, single state root. Genre-specific features build on this shared architecture.' },

  // L20, L25: BT only
  { file: 'lesson-shooter-20-milestone-pooled-lifecycle.ts',
    bt: '**Not verifying that pool recycling actually works.** Spawn 100 bullets, destroy them all, spawn 100 more. If the second batch uses different memory than the first, the pool is leaking. Track alloc count to verify zero-allocation recycling.' },
  { file: 'lesson-shooter-25-milestone-restart-resume.ts',
    bt: '**Testing restart but not resume.** A restart that works does not prove load works. Save, quit, load, verify the state signature matches. The round-trip test is the real proof.' },

  // L27-L29: BT, EI, ST
  { file: 'lesson-shooter-27-powerup-entities-v0.ts',
    bt: '**Allocating new powerup entities on the heap instead of using the entity pool.** Powerups spawn and despawn frequently. If each spawn calls new, you reintroduce heap allocation in the game loop. Use the existing entity pool.',
    ei: 'Arcade games from R-Type to Gradius spawned powerups from the same entity pool as enemies and bullets. One pool, multiple entity types, zero allocation. Your powerup pool follows the same classic design.',
    st: 'The RPG spawns loot from entity pools (L28). The Crawler spawns items from pools. Pool-based entity management is universal — the entity type (bullet, enemy, powerup) is just a tag on a pool slot.' },
  { file: 'lesson-shooter-28-allocation-counter-v0.ts',
    bt: '**Ignoring allocations that happen "only once per wave."** Even one allocation per wave is a stall that can cause a frame spike during gameplay. The goal is zero — no exceptions, no excuses.',
    ei: 'Carmack set the standard: zero heap allocations during gameplay. Every Doom and Quake title pre-allocates all memory at startup. Your allocation counter makes this discipline measurable and enforceable.',
    st: 'RPG (L29) and Crawler (L29) track the same metric. The Platformer (L28) does too. Allocation counting is the universal health check — every path must prove zero heap activity during the game loop.' },
  { file: 'lesson-shooter-29-leak-trap-demo.ts',
    bt: '**Deleting the "leaked" object to fix the demo.** The point of the leak trap is to demonstrate what happens when you use new without delete. Fixing it defeats the lesson. Leave the leak, show the counter increasing, then show the pool-based alternative.',
    ei: 'Memory leak detection tools like Valgrind and AddressSanitizer catch leaks by tracking every allocation. Your allocation counter is a manual version of the same idea — instrument the allocator, verify everything is freed.',
    st: 'RPG (L29) and Platformer (L29) demonstrate the same leak trap. The lesson is universal: heap allocation in the game loop is a bug, and pools are the cure. Every path proves immunity by showing the counter stays at zero.' },

  // L30: BT, ST (already has EI)
  { file: 'lesson-shooter-30-gate-a-heap-freeze.ts',
    bt: '**Thinking "zero allocations" means "no dynamic behavior."** Pre-allocated pools give you all the dynamic behavior you need — spawn, despawn, recycle — without touching the heap. The constraint is on allocation, not on dynamism.',
    st: 'RPG L30, Platformer L30, and Crawler L30 all hit the same gate. Heap freeze is the most universal engineering gate in the curriculum — four paths, one standard: zero allocations in the game loop.' },

  // L31-L50: All need BT, EI, ST
  { file: 'lesson-shooter-31-input-module-split.ts',
    bt: '**Reading input in multiple places.** If movement reads IsKeyDown(KEY_LEFT) and shooting reads it independently, you get inconsistent behavior when both systems run in the same frame. Read input once into a snapshot struct, pass it to all systems.',
    ei: 'Unreal separates input into a dedicated input system that runs before all other systems. The input snapshot is the "single source of truth" for the frame. Your inputSystem follows the same architecture.',
    st: 'RPG (L31) and Platformer (L31) split input the same way. The Crawler records raw input for replays. Input isolation is the first module split in every path — it sets the pattern for all subsequent system extractions.' },
  { file: 'lesson-shooter-32-render-module-split.ts',
    bt: '**Calling DrawRectangle inside the update loop.** Rendering mixed with game logic means you cannot change the draw order without changing the update order. Separate update and render into distinct passes that run in sequence.',
    ei: 'Every game engine separates update from render. The update pass modifies state. The render pass reads state and draws. This separation enables double-buffering, fixed timestep, and headless testing (update without render).',
    st: 'RPG (L32) and Platformer (L32) split render the same way. The Crawler renders in a separate BeginMode3D block. Update-then-render is the universal game loop pattern, discovered independently by every engine developer.' },
  { file: 'lesson-shooter-33-movement-system-split.ts',
    bt: '**Updating positions with raw frame delta inside the movement system.** If frame rate varies, entities move faster on faster machines. Use a fixed timestep delta for movement calculations inside the system.',
    ei: 'Separating movement into its own system enables "physics-only" updates for replay, prediction, and testing. You can run movementSystem() without rendering to simulate the game headlessly.',
    st: 'RPG (L17) isolates its resolve pass. Platformer (L33) isolates physics. Each path extracts movement into a standalone system — the name differs (resolve, physics, movement) but the isolation principle is identical.' },
  { file: 'lesson-shooter-34-collision-system-split.ts',
    bt: '**Applying collision responses (deactivate, deal damage) inside the detection loop.** Detect all collisions first into a result list, then apply responses in a separate pass. Mixing detection with response creates order-dependent bugs.',
    ei: 'Professional physics engines split collision into broadphase (find potential pairs), narrowphase (exact test), and resolution (apply response). Your split follows the same pipeline: detect first, respond second.',
    st: 'RPG (L18) isolates combat resolution. Platformer (L34) isolates collision response. The Crawler separates hit detection from damage. Detection-then-resolution prevents order-dependent bugs in every game genre.' },
  { file: 'lesson-shooter-35-gate-b-system-pipeline.ts',
    bt: '**Running systems in arbitrary order.** If collision runs before movement, you detect collisions with stale positions. Define and enforce the pipeline order: Input > Movement > Collision > Cleanup > Render.',
    ei: 'Unity defines execution order numerically. Unreal uses tick groups. ECS frameworks use explicit system scheduling. Your gameFrame() function is the manual equivalent — a fixed pipeline that guarantees execution order.',
    st: 'RPG (L15) and Platformer (L35) enforce the same system pipeline. The Crawler runs 3D systems in a fixed order. Pipeline ordering is a universal architecture constraint — every path must guarantee systems run in the correct sequence.' },
  { file: 'lesson-shooter-36-spatial-grid-v0.ts',
    bt: '**Using a grid cell size smaller than the largest entity.** If a bullet is smaller than the cell, it fits in one cell. If an enemy is larger, it spans multiple cells and requires checking all neighboring cells. Size the grid to the entity that matters most.',
    ei: 'The spatial grid (uniform grid acceleration structure) trades memory for speed: O(1) cell lookup instead of O(n) linear scan. Every physics engine uses spatial acceleration — grids for uniform entity sizes, BVH for mixed sizes.',
    st: 'The RPG uses direct grid lookup (grid[y][x]). The Crawler uses spatial hashing (L54). Your uniform grid is the 2D-optimized version — same goal (fast neighbor queries), different data structures tuned to different entity distributions.' },
  { file: 'lesson-shooter-37-wave-spawner-v0.ts',
    bt: '**Spawning the next wave before the current wave is cleared.** If waves overlap, the screen fills with enemies and the player is overwhelmed. Check that all enemies from the current wave are dead before spawning the next wave.',
    ei: 'Wave-based spawning is a game design pattern from Space Invaders: clear the screen, advance difficulty, spawn the next formation. The spawner is a state machine: Spawning > Active > Cleared > NextWave.',
    st: 'The RPG spawns enemies from room data on transition. The Crawler generates enemies per floor. Your wave spawner is the shooter-specific version — timed enemy waves that escalate difficulty, driven by data tables.' },
  { file: 'lesson-shooter-38-hud-system-v0.ts',
    bt: '**Drawing HUD text using game-world coordinates instead of screen coordinates.** The HUD should be drawn after EndMode2D (or in screen space), not inside the game-world rendering pass. HUD elements are screen-anchored, not world-anchored.',
    ei: 'Every game engine draws the HUD as a separate pass after world rendering. The HUD reads observable state (score, HP, wave) and draws text/icons at screen positions. Your hudSystem follows the same decoupled architecture.',
    st: 'RPG (L81) and Platformer (L81) implement HUD systems too. The Crawler draws 3D HUD overlays. HUD rendering is always the last draw pass — it reads game state without modifying it, making it trivially parallelizable.' },
  { file: 'lesson-shooter-39-error-handling.ts',
    bt: '**Silently failing when the pool is full.** If spawnBullet returns quietly when the pool is exhausted, the player stops shooting without feedback. Log the failure, track spawn_fails, and consider increasing pool size or cleaning up stale entities.',
    ei: 'Defensive programming in games means "never crash, always degrade gracefully." If the pool is full, skip the spawn and log a warning. The game continues, and the developer sees the warning in the console.',
    st: 'RPG (L88) and Crawler crash-proof at system boundaries. Platformer (L88) validates input ranges. Error handling at pool boundaries is a universal robustness pattern — every path must handle "resource exhausted" gracefully.' },
  { file: 'lesson-shooter-40-milestone-modular-shooter.ts',
    bt: '**Declaring "modular" without listing every system and its order.** Print the system inventory: inputSystem, movementSystem, collisionSystem, waveSystem, hudSystem, renderSystem. If you cannot list them all, your architecture is not fully modular.',
    ei: 'System inventories are a standard architecture document in professional game development. "What systems exist, and in what order do they run?" answers most architecture questions. Your milestone verifies this documentation.',
    st: 'RPG (L40) and Platformer (L40) validate the same modularity milestone. Every path must demonstrate that all systems are isolated, named, and ordered. The module list is the architecture specification.' },
  { file: 'lesson-shooter-41-wave-table-parse.ts',
    bt: '**Hardcoding wave data in the spawner instead of reading from a table.** Each new wave requires a code change. A WaveConfig struct array lets designers add waves by adding data rows, not by editing game logic.',
    ei: 'Data-driven design separates content (wave definitions) from code (wave spawner logic). Halo level designers created encounters in data files without touching engine code. Your wave table follows the same principle.',
    st: 'RPG uses room data tables. Crawler uses loot tables (L48). Platformer uses level data arrays. Every path separates content from code — the table format varies, but the principle of data-driven design is universal.' },
  { file: 'lesson-shooter-42-enemy-types-v0.ts',
    bt: '**Creating a new class for each enemy type.** Classes with virtual methods add indirection and break SoA layout. Use an enum type field and a stat table: each enemy type is a row of numbers, not a class hierarchy.',
    ei: 'Composition over inheritance is the core insight of ECS. Unity abandoned MonoBehaviour inheritance for DOTS components. Your enum + stat table approach achieves the same result: new enemy types are data, not code.',
    st: 'RPG uses strategy tables (L78) for enemy behavior. Crawler uses spawn budgets with type IDs (L46). Data-driven entity types scale to any number of types without code changes — the professional standard across all game genres.' },
  { file: 'lesson-shooter-43-powerup-system.ts',
    bt: '**Applying powerup effects permanently instead of with a timer.** A speed boost that never expires trivializes the game. Powerups should have a duration: apply effect, start timer, remove effect when timer expires.',
    ei: 'Gradius, R-Type, and Galaga all use timed powerups. The design pattern: collect -> apply buff -> start timer -> remove buff. Your type-dispatched collectPowerup follows the same approach with explicit timer management.',
    st: 'RPG uses timed status effects. Crawler uses timed item effects. The Platformer applies timed dash and invulnerability buffs. Timed powerups are a universal game design pattern — collect, buff, expire.' },
  { file: 'lesson-shooter-44-spread-shot.ts',
    bt: '**Spawning spread bullets at the same position with the same velocity.** If all three bullets start at the same point and move at the same speed, they overlap into one visible bullet. Offset the angles: -15, 0, +15 degrees creates a visible fan.',
    ei: 'Spread shot patterns date back to Contra and Gradius. The fan is defined by (count, angle_spread) — a data-driven weapon mode. Adding new weapon types means adding data entries, not new code paths.',
    st: 'The RPG has no projectile patterns. The Crawler fires single projectiles (L59). Your spread shot system is the most weapon-diverse across all paths — weapon modes as data enable unlimited projectile patterns.' },
  { file: 'lesson-shooter-45-milestone-wave-loop.ts',
    bt: '**Declaring the wave loop complete without testing wave 10+.** Early waves are easy. Late waves stress the spawner, the pool, the collision system, and the scoring. Test at least 15 waves to find the scaling cliff.',
    ei: 'Arcade game design is fundamentally about the wave loop: escalating challenge that eventually overwhelms the player. The loop must feel fair at every difficulty level. Your milestone tests this curve.',
    st: 'RPG validates the combat loop milestone. Crawler validates the roguelike run. Every path has a "gameplay loop" milestone that proves the core experience works end-to-end under escalating pressure.' },
  { file: 'lesson-shooter-46-score-multiplier.ts',
    bt: '**Resetting the multiplier immediately when a kill streak breaks.** A 0.5-second grace period prevents frustrating resets from tiny timing errors. The combo system should forgive small gaps, not demand perfection.',
    ei: 'Combo systems from fighting games to rhythm games use a "grace window" — a short timer that keeps the combo alive between hits. Your kill-streak multiplier follows the same UX principle: reward consistency, forgive small gaps.',
    st: 'RPG uses combat combos. Platformer uses speed-run timers. The Crawler tracks kill streaks in rooms. Score multipliers are a game-feel feature that rewards skilled play — the implementation varies, but the psychological effect is universal.' },
  { file: 'lesson-shooter-47-difficulty-curve-v0.ts',
    bt: '**Scaling enemy speed linearly per wave.** Linear scaling means wave 20 enemies are 20x faster than wave 1 — impossible to dodge. Use diminishing returns: wave_speed = base + log(wave) * factor. The curve should challenge, not punish.',
    ei: 'Resident Evil 4 adjusts difficulty based on player performance using internal difficulty tables. Your lookup table approach is the data-driven foundation — designers can tune the curve without recompiling.',
    st: 'RPG (L87) and Crawler (L47) implement difficulty scaling too. Every path faces the same design challenge: escalating difficulty must match player skill growth. Data tables make tuning possible without code changes.' },
  { file: 'lesson-shooter-48-background-scrolling.ts',
    bt: '**Scrolling one layer without wrapping.** A background that scrolls off-screen leaves black. Wrap the scroll position: when pos > height, reset to 0. Two copies of the background drawn at offset positions create seamless looping.',
    ei: 'Parallax scrolling — multiple layers scrolling at different speeds — creates the illusion of depth in 2D. Every side-scroller from Sonic to Hollow Knight uses this technique. Your star field is the vertical-scrolling version.',
    st: 'The Platformer uses parallax backgrounds (L78). The RPG has no scrolling (top-down grid). The Crawler uses 3D perspective for depth. Your scrolling star field is the shooter-specific depth illusion — movement creates the feeling of flying through space.' },
  { file: 'lesson-shooter-49-lives-system.ts',
    bt: '**Respawning the player instantly after death.** Without a brief invulnerability period, the player can die repeatedly in the same frame from overlapping enemies. Add 1-2 seconds of invulnerability after respawn.',
    ei: 'Every classic arcade game grants brief invulnerability after death — flashing sprites in Pac-Man, a shield in Galaga. The "mercy invincibility" pattern prevents frustrating chain deaths.',
    st: 'RPG has HP and death. Platformer has lives and checkpoints. Crawler has permadeath. Your lives system with mercy invincibility is the arcade-standard approach — the most forgiving death model across all four paths.' },
  { file: 'lesson-shooter-50-milestone-midgame-slice.ts',
    bt: '**Treating the midgame slice as "half done."** This milestone is a vertical slice — every system works, even if content is minimal. Waves, powerups, scoring, lives, difficulty, and HUD must all function together.',
    ei: 'Vertical slice milestones in professional development prove that all systems integrate correctly. The slice may only have 5 minutes of content, but every system is represented. Your midgame milestone follows this approach.',
    st: 'RPG L50, Platformer L50, and Crawler L50 all hit the same midgame milestone. The vertical slice proves architecture completeness — genre-specific features are built, connected, and tested before the second half of development.' },

  // L51-L70: ECS, AI, Boss, Save, Replay
  { file: 'lesson-shooter-51-component-flags.ts',
    bt: '**Using separate booleans for each component presence.** Booleans waste memory and require individual checks. A single bitmask (uint32_t flags) stores 32 component flags in one integer. Check with bitwise AND: if (flags & HAS_VELOCITY).',
    ei: 'EnTT and flecs use bitmask-based archetype queries — each component type has a bit, and queries check the bitmask in one operation. Your component flags implement the same O(1) "does this entity have component X?" check.',
    st: 'The RPG and Crawler use simpler entity type enums. Your bitmask approach is the most ECS-native across all paths — it enables arbitrary component combinations without predefined entity types.' },
  { file: 'lesson-shooter-52-system-ordering-rules.ts',
    bt: '**Assuming system order does not matter.** If the collision system reads positions that the movement system has not yet updated, it detects collisions at stale positions. Document and enforce the dependency graph: movement before collision, collision before cleanup.',
    ei: 'Unity defines script execution order numerically (-100 before 0 before 100). Unreal uses tick groups with explicit dependencies. Your ordered system array is the manual equivalent of the same scheduling guarantee.',
    st: 'RPG enforces update order (L15). Platformer enforces pipeline order (L35). The ordering problem is universal: when systems share data, the order they run determines correctness. Every path enforces this explicitly.' },
  { file: 'lesson-shooter-53-enemy-ai-linear.ts',
    bt: '**Normalizing the direction vector without checking for zero length.** If the enemy is exactly at the player position, the direction is (0,0) and normalizing divides by zero. Always check length > epsilon before normalizing.',
    ei: 'Linear pursuit — moving directly toward the target at constant speed — is the simplest AI behavior. It is also the most predictable and the easiest to dodge. Professional games use it for weak enemies and replace it with smarter behaviors for elites.',
    st: 'RPG enemies chase on a grid (L06). Crawler enemies chase in 3D (L37). Your linear pursuit is the 2D continuous-space version. All paths start with "move toward player" and later add complexity (patrol, flank, flee).' },
  { file: 'lesson-shooter-54-enemy-ai-wave-pattern.ts',
    bt: '**Using frame count for the sine wave instead of elapsed time.** Frame-count-based oscillation runs at different speeds on different machines. Use elapsed_time * frequency for consistent wave patterns regardless of frame rate.',
    ei: 'Sine-wave enemy patterns are a staple of the shoot-em-up genre — from Gradius to Raiden. The pattern is purely mathematical: x = base_x + amplitude * sin(time * frequency). No AI logic needed, just trigonometry.',
    st: 'The Platformer uses sine curves for moving platforms (L38). The Crawler does not use wave patterns (grid-based movement). Math-driven motion is the simplest form of "AI" — predictable, beautiful, and computationally free.' },
  { file: 'lesson-shooter-55-milestone-smart-enemies.ts',
    bt: '**Testing AI with only one enemy type.** If all enemies use linear pursuit, there is no variety. The milestone requires at least two distinct behaviors (linear + wave) coexisting in the same wave.',
    ei: 'Enemy variety is what separates a good shooter from a great one. Galaga had divebombers and formations. Your behavior system enables the same variety — different AI types create emergent gameplay patterns.',
    st: 'RPG uses data-driven enemy behaviors (L78). Crawler uses patrol/chase FSMs (L37). Your behavior-per-type system is the shooter version — each enemy type has a behavior ID that selects its movement pattern.' },
  { file: 'lesson-shooter-56-boss-entity-v0.ts',
    bt: '**Giving the boss the same pool slot as regular enemies.** The boss needs more state (HP bar, attack phase, attack timer) than regular enemies. Either use a dedicated boss struct or add boss-specific components to the ECS.',
    ei: 'Boss fights in shmups from R-Type to Ikaruga are multi-phase encounters with distinct attack patterns per phase. The boss is the most complex entity in the game — it tests your architecture under maximum load.',
    st: 'RPG implements boss entities with similar complexity. Platformer adds boss entities (L56). The Crawler has no bosses yet. Boss entities test whether your entity system can handle entities with significantly more state than normal enemies.' },
  { file: 'lesson-shooter-57-boss-attack-patterns.ts',
    bt: '**Hardcoding attack patterns in if/else chains.** Each new pattern means more branches. Store patterns as data: { type: SPIRAL, bullet_count: 12, angle_step: 30, speed: 3.0 }. The attack system reads data, not code.',
    ei: 'Bullet-pattern games (danmaku/bullet-hell) define attacks as data — angle, speed, count, timing. Touhou and Ikaruga encode hundreds of patterns without unique code for each. Your data-driven patterns follow the same philosophy.',
    st: 'RPG defines attack types in combat tables. Crawler defines enemy attacks as data (L39). Data-driven attack definitions are universal: designers create content by editing data, not by writing and debugging new code.' },
  { file: 'lesson-shooter-58-shield-component.ts',
    bt: '**Checking shield status in the damage function instead of the collision system.** The shield should prevent the collision response (damage), not just reduce it. Check shield before applying damage: if shielded, skip damage entirely.',
    ei: 'Time-limited components (shields, buffs, invulnerability) are timer-driven: each frame, decrement the timer. When the timer hits zero, remove the component. This pattern applies to any temporary state in any game.',
    st: 'RPG uses timed status effects. Platformer uses invulnerability frames (L54). Crawler grants temporary buffs. Timer-based components are the universal pattern for temporary state — the implementation is identical across all paths.' },
  { file: 'lesson-shooter-59-entity-tags-v0.ts',
    bt: '**Using string tags instead of enum/bitmask tags.** String comparison is slow and error-prone ("Enemy" vs "enemy" vs "ENEMY"). Use integer enum tags or bitmask flags for O(1) tag checks.',
    ei: 'ECS engines use archetype tags for filtered queries: "give me all entities with Position + Velocity but not Dead." Your tag bitmask enables the same pattern — filter entities by capability, not by type name.',
    st: 'RPG uses entity type enums. Crawler uses type IDs for enemies. Bitmask-based entity classification scales to complex queries (all enemies with shields that are not dead) without string comparisons or inheritance.' },
  { file: 'lesson-shooter-60-milestone-ecs-engine.ts',
    bt: '**Declaring ECS complete without testing entity reuse.** Create 100 entities, destroy them all, create 100 more. If the second batch works identically, your ECS handles the full lifecycle. If not, your pool or ID system has a bug.',
    ei: 'A complete ECS needs: entity creation, component attachment, system iteration, entity destruction, and slot reuse. Your milestone tests all five operations. Professional ECS frameworks test these with automated stress tests.',
    st: 'RPG reaches its architecture milestone at L40. Platformer and Crawler reach theirs at similar points. The ECS milestone proves your entity system can handle any number of entity types and behaviors without architectural changes.' },
  { file: 'lesson-shooter-61-save-v1-versioned.ts',
    bt: '**Storing the version number at the end of the file instead of the beginning.** If you read the version first, you can choose the correct deserialization logic before reading any data. Version at the end is useless — you have already read everything.',
    ei: 'PNG, ZIP, and SQLite all store a magic number and version in the first few bytes. File format design always puts identification first. Your versioned save follows the same standard.',
    st: 'RPG (L24) and Crawler (L61) implement versioned saves the same way. Every path stores version first, then data. The serialization pattern is universal because the problem (forward compatibility) is universal.' },
  { file: 'lesson-shooter-62-save-checksum.ts',
    bt: '**Computing the checksum over the entire file including the checksum field itself.** The checksum must be computed over the data, then appended. On load, compute the checksum over the data portion and compare to the stored value.',
    ei: 'CRC32, used in ZIP files and network protocols, detects accidental corruption with 99.998% reliability. Your save checksum follows the same pattern: hash the data, store the hash, verify on load.',
    st: 'RPG and Crawler implement save checksums too. The Platformer stores checkpoint integrity hashes. Data integrity verification is a universal requirement for any system that persists state to disk.' },
  { file: 'lesson-shooter-63-load-migration.ts',
    bt: '**Failing to load old save files after a format change.** Players lose progress. Migration means: read old format, convert to new format, save in new format. Each version bump needs a migration function.',
    ei: 'Database migrations (Rails, Django, Flyway) apply sequential transforms to upgrade schema. Game save migration is the same problem: each version change needs a transform function. Your version-checked loader follows the same pattern.',
    st: 'RPG (L24) and Crawler (L62) handle save migration. Every path faces the same challenge: game updates must not break existing save files. Version-checked deserialization with migration is the standard solution.' },
  { file: 'lesson-shooter-64-input-log-v0.ts',
    bt: '**Recording processed game actions instead of raw key states.** Replays must reproduce the exact input. If you record "fired bullet at (100, 50)" instead of "SPACE key down at frame 847," the replay cannot handle code changes that alter bullet behavior.',
    ei: 'Doom recorded raw input as "tics" — one complete input snapshot per game frame. This made .lmp demo files tiny and perfectly reproducible. Your per-frame input log follows the same design from 1993.',
    st: 'RPG, Crawler, and Platformer all record raw input per frame. The input types differ (keyboard, mouse+keyboard, 2D, 3D) but the principle is identical: capture raw input, not derived actions.' },
  { file: 'lesson-shooter-65-milestone-replay-a-run.ts',
    bt: '**Testing replay for only 10 frames.** Determinism bugs often appear hundreds of frames in. Record a full 60-second gameplay session, replay it, and verify the state signature matches at every frame.',
    ei: 'Speedrun communities rely on replay files to verify world records. A replay that diverges is evidence of cheating or a bug. Your replay milestone tests the same guarantee: input in, deterministic output.',
    st: 'RPG, Crawler, and Platformer all hit the same replay milestone. The test is identical: play, record, replay, verify. Determinism is a cross-path requirement because replay and save/load both depend on it.' },
  { file: 'lesson-shooter-66-replay-playback-pipeline.ts',
    bt: '**Mixing live input with replay input.** During playback, the game should read from the input log, not from the keyboard. Swap the input source: live mode reads hardware, replay mode reads the log. The rest of the game does not know the difference.',
    ei: 'The "input source abstraction" pattern lets the same game loop accept live input, recorded input, or network input. Professional engines use this for replays, tutorials, and AI bots. Your source swap follows the same pattern.',
    st: 'RPG, Crawler, and Platformer implement the same input source swap. The abstraction is identical: the game loop reads from an InputSnapshot interface, and the source (live, replay, network) is swapped externally.' },
  { file: 'lesson-shooter-67-determinism-pitfalls.ts',
    bt: '**Using std::sort without a stable comparator.** std::sort is not guaranteed to be stable — equal elements can swap order between runs. Use std::stable_sort or add a tiebreaker (entity ID) to the comparator.',
    ei: 'Floating-point determinism is the #1 cause of lockstep desync in networked games. Different compilers optimize x87 vs SSE differently. Your pitfall catalog documents the traps that catch every game developer.',
    st: 'RPG, Crawler, and Platformer face the same pitfalls. Iteration order, unstable sort, and floating-point precision affect every path equally. The determinism discipline is shared across all game genres.' },
  { file: 'lesson-shooter-68-state-signature-at-end.ts',
    bt: '**Only hashing entity positions and forgetting score, lives, and wave number.** Every gameplay-relevant value must be in the signature. If the score diverges but the hash does not catch it, your signature is incomplete.',
    ei: 'Age of Empires computes a per-frame hash of all game state for multiplayer sync checking. Any divergence triggers a resync. Your end-of-frame signature serves the same purpose for single-player replay verification.',
    st: 'RPG (L23), Crawler (L64), and Platformer all compute state signatures. The hash function and included fields differ, but the purpose is identical: detect state divergence between recording and playback.' },
  { file: 'lesson-shooter-69-replay-verification-test.ts',
    bt: '**Running the verification only once.** A test that passes with one seed may fail with another. Run verification with at least 5 different seeds and gameplay styles to catch determinism bugs that depend on specific sequences.',
    ei: 'Professional QA runs hundreds of automated replay tests nightly — each with different seeds, durations, and player behaviors. Your verification test should cover diverse scenarios, not just the happy path.',
    st: 'RPG, Crawler, and Platformer run the same replay verification tests. The testing pattern is path-universal: record diverse sessions, replay them all, assert zero signature mismatches.' },
  { file: 'lesson-shooter-70-gate-b-replay-determinism.ts',
    bt: '**Passing the gate with a short replay.** A 10-second replay might pass when a 5-minute replay fails. Long sessions expose subtle drift from floating-point accumulation or uninitialized memory. Test with extended gameplay.',
    ei: 'Lockstep determinism is proven by extended testing under varied conditions. Professional studios run overnight replay suites to build confidence. Your gate requires the same evidence: multiple long replays, zero divergence.',
    st: 'RPG L70, Crawler L70, and Platformer L70 all hit the same gate. Replay determinism is the most engineering-intensive gate in the curriculum — all four paths must prove bit-perfect reproducibility.' },

  // L71-L80: Performance
  { file: 'lesson-shooter-71-profiling-timers.ts',
    bt: '**Profiling in debug mode.** Debug builds add bounds checking, assertion evaluation, and disable optimizations. Always profile with -O1 or higher. The hot path in debug may not be the hot path in release.',
    ei: 'Carmack profiled Doom and Quake with custom timing macros — measuring each system pass independently. Modern tools (Tracy, Optick) automate this, but the principle is the same: measure before optimizing.',
    st: 'RPG L71, Crawler L51, and Platformer L71 all add profiling timers. Measurement is the first step of optimization in every path — you cannot improve what you have not measured.' },
  { file: 'lesson-shooter-72-hot-path-audit.ts',
    bt: '**Optimizing a function that takes 0.1ms when another takes 4ms.** The hot path is the code that consumes the most frame time. Optimize the biggest bottleneck first. Profiling data tells you what to fix.',
    ei: 'The Pareto principle applies to optimization: 20% of the code consumes 80% of the frame time. Audit the hot path — the inner loops of collision, movement, and rendering — and leave cold code alone.',
    st: 'RPG (L72) and Platformer (L72) audit their hot paths too. Every path converges on the same optimization discipline: profile, identify the bottleneck, optimize it, re-profile to verify the improvement.' },
  { file: 'lesson-shooter-73-spatial-grid-tuning.ts',
    bt: '**Using a 1x1 pixel cell size.** Too-small cells waste memory and iteration time. Too-large cells put too many entities per cell. Optimal cell size is roughly 2x the average entity size — enough to hold neighbors in adjacent cells.',
    ei: 'Spatial grid tuning is a classic space-time tradeoff. Smaller cells = more cells to check, fewer entities per cell. Larger cells = fewer cells to check, more entities per cell. Profile to find the sweet spot.',
    st: 'The Crawler tunes spatial hash bucket size (L54). RPG tunes grid cell size (L73). Every path with spatial acceleration faces the same tuning problem — cell size determines the performance curve.' },
  { file: 'lesson-shooter-74-pool-stats.ts',
    bt: '**Setting pool capacity based on average usage instead of peak usage.** Pools must handle the worst case, not the average case. Track peak_used across the entire session and size the pool to peak + margin.',
    ei: 'Memory pool monitoring is standard in professional engines. Unity profiler shows pool utilization. Unreal tracks peak object counts. Your pool stats dashboard is the manual equivalent of the same diagnostic.',
    st: 'RPG (L74) and Crawler audit pool utilization. Platformer (L74) does too. Pool sizing is a universal optimization task — too small causes overflow, too large wastes memory. Peak tracking guides the right size.' },
  { file: 'lesson-shooter-75-milestone-stress-test.ts',
    bt: '**Stress testing with the same number of entities as normal gameplay.** The point is to find the breaking point. Spawn 200+ bullets, 50+ enemies, and 10+ powerups simultaneously. If frame rate stays above 60fps, the architecture scales.',
    ei: 'Professional studios run "soak tests" — leaving the game running under maximum load for hours. Memory leaks, frame drops, and crashes that hide during normal play surface under sustained stress. Your test follows the same principle.',
    st: 'RPG (L75) stress tests with 50 entities. Crawler (L55) tests render optimization. Every path proves performance at scale — the entity count differs, but the principle is identical: verify the architecture handles peak load.' },
  { file: 'lesson-shooter-76-simd-ready-layout.ts',
    bt: '**Aligning data to arbitrary boundaries.** SIMD operations require specific alignment (16 bytes for SSE, 32 for AVX). Use alignas(16) on arrays that will be processed with SIMD intrinsics. Misaligned SIMD access is either slow or crashes.',
    ei: 'Data-oriented design is SIMD-ready by nature — contiguous arrays of floats align naturally and process in batches. Mike Acton demonstrated 100x speedups by aligning position arrays for SSE4 processing on PS3.',
    st: 'RPG and Crawler do not need SIMD (low entity counts). Platformer could benefit but does not implement it. Your SIMD-ready layout is the most performance-advanced optimization across all four paths.' },
  { file: 'lesson-shooter-77-batch-rendering.ts',
    bt: '**Calling DrawRectangle once per entity instead of batching.** Each draw call has CPU overhead. Sorting entities by color and drawing all same-colored entities in one batch reduces draw call count dramatically.',
    ei: 'Sprite batching is the #1 2D rendering optimization. Unity SpriteRenderer batches by material. Your sort-by-color-then-draw approach is the software equivalent — minimize state changes between draw calls.',
    st: 'RPG could batch tile rendering. Crawler batches 3D cube draws. Platformer could batch sprites. Draw call reduction through batching is a universal rendering optimization — fewer state changes means faster rendering.' },
  { file: 'lesson-shooter-78-prefetch-hints.ts',
    bt: '**Prefetching data that is already in cache.** Prefetch only helps for data that will be accessed several iterations later. Prefetch entity[i+4] while processing entity[i] — far enough ahead to hide memory latency.',
    ei: 'Cache prefetch hints (__builtin_prefetch on GCC, _mm_prefetch on MSVC) tell the CPU to load data before it is needed. Professional game engines use prefetch in tight entity loops to hide memory access latency.',
    st: 'RPG and Crawler entity counts are too small for prefetch to help. Platformer might benefit in tile rendering. Your prefetch optimization is the most CPU-architecture-aware technique across all four paths.' },
  { file: 'lesson-shooter-79-memory-layout-report.ts',
    bt: '**Assuming sizeof(struct) equals the sum of field sizes.** Compilers add padding for alignment. sizeof(struct { char a; int b; }) is often 8, not 5. Use offsetof to verify actual field positions and find wasted padding bytes.',
    ei: 'Reordering struct fields to minimize padding is a standard optimization. Sort fields by size (largest first) to reduce wasted bytes. Professional engines audit struct layouts to ensure cache-line-friendly data.',
    st: 'RPG and Crawler use simpler structs. Platformer does not audit memory layout. Your sizeof/offsetof report is a unique systems-level diagnostic that directly connects to CPU cache architecture.' },
  { file: 'lesson-shooter-80-milestone-perf-report.ts',
    bt: '**Writing "performance is good" without numbers.** A performance report needs data: frame time (ms), entity count, draw calls, memory usage, pool utilization. Subjective "feels fast" is not a metric.',
    ei: 'Professional game studios produce performance reports with every milestone build. The report includes frame budget breakdown, regression comparisons, and target hardware results. Your report follows the same standard.',
    st: 'RPG (L75), Crawler (L55), and Platformer (L80) produce similar reports. The metrics differ by genre, but every path must quantify performance with real numbers, not subjective impressions.' },

  // L81-L100: Polish and Ship
  { file: 'lesson-shooter-81-hud-v2-layout.ts',
    bt: '**Using absolute pixel positions for HUD elements.** If the window resizes, all positions break. Use anchor-relative positions: "10px from top-left" adapts to any resolution. Anchor + offset is the professional UI pattern.',
    ei: 'Every professional game engine uses anchor-based UI layout. Unity Canvas, Unreal UMG, and Godot Control nodes all position elements relative to screen edges or parent containers, never absolute pixels.',
    st: 'RPG (L81) and Platformer (L81) implement the same anchor-based HUD. The Crawler overlays 3D HUD elements. HUD architecture is identical across all paths — only the displayed information differs by genre.' },
  { file: 'lesson-shooter-82-screen-shake-v0.ts',
    bt: '**Applying screen shake by moving entity positions instead of offsetting the camera.** Moving entities permanently displaces them. Shake should be a temporary render-time offset applied to the camera or the draw position, never to the game state.',
    ei: 'Vlambeer (Nuclear Throne) popularized screen shake as a "game feel" essential. A 3-frame, 4-pixel shake on enemy death makes the game feel impactful. The effect is pure presentation — no game state is modified.',
    st: 'RPG (L82) adds combat feedback. Platformer (L82) adds screen shake. Crawler could add first-person camera shake. Screen shake is the simplest high-impact juice effect — render-only, zero gameplay side effects.' },
  { file: 'lesson-shooter-83-particle-burst.ts',
    bt: '**Allocating particles with new/malloc.** Particles spawn in bursts (10-50 at once) and die quickly. Use a fixed-size particle pool. Pre-allocate 256 particles and cycle through them. Zero allocation, maximum visual impact.',
    ei: 'Every particle system in professional engines uses pool allocation. Particles are the most allocation-intensive system in any game. Pool-based particles maintain the heap-freeze guarantee under heavy visual effects.',
    st: 'RPG uses sprite animation for feedback. Platformer (L83) adds particle effects. Crawler (L58) implements a full particle system. Pool-based particles are universal — the visual effect varies, the allocation pattern is identical.' },
  { file: 'lesson-shooter-84-sprite-animation-v0.ts',
    bt: '**Advancing animation frames using a frame counter instead of delta time.** On a 120fps monitor, animations play twice as fast. Use a time accumulator: add dt, advance frame when accumulator > frame_duration.',
    ei: 'Sprite animation with time accumulators is the industry standard — frame rate independent, tunable frame durations, and trivial to implement. Every 2D engine uses this approach internally.',
    st: 'RPG (L83) and Platformer (L84) implement the same delta-time animation. The Crawler uses 3D model animation. Frame-rate-independent animation is mandatory across all paths — the technique is universal.' },
  { file: 'lesson-shooter-85-milestone-juiced-shooter.ts',
    bt: '**Adding juice without measuring frame impact.** Screen shake, particles, and animations all cost CPU time. Profile the render pass before and after juice effects. If effects drop the frame rate, simplify or cull distant effects.',
    ei: 'Game feel ("juice") is the difference between a prototype and a product. Jan Willem Nijman (Vlambeer) lists screen shake, particles, hit flash, and sound as the minimum juice checklist. Your milestone tests all four.',
    st: 'RPG (L85), Platformer (L85), and Crawler (L60) all hit juice milestones. The effects differ by genre (2D particles vs 3D particles vs sprite flashes) but the principle is universal: feedback makes games feel alive.' },
  { file: 'lesson-shooter-86-difficulty-config.ts',
    bt: '**Storing difficulty values in code instead of a config struct.** Hardcoded values require recompilation to tune. A DifficultyConfig struct that the game reads at startup enables tuning without rebuilding.',
    ei: 'Professional games externalize balance data — enemy HP, spawn rates, scoring — into data files. Designers iterate on balance by changing data, not code. Your config struct is the first step toward this workflow.',
    st: 'RPG (L87) and Crawler (L47) implement data-driven difficulty. Every path externalizes balance into data. The config format varies (struct, table, file) but the principle is identical: separate tuning from logic.' },
  { file: 'lesson-shooter-87-assist-mode.ts',
    bt: '**Making assist mode a single "easy" toggle.** Players need granular control: slower enemies, more lives, wider hit detection. Independent toggles respect player agency more than a binary easy/normal/hard selection.',
    ei: 'Celeste pioneered granular assist mode: game speed, stamina, invincibility, and dash count as independent sliders. The key insight: accessibility is not one toggle but a set of dials players combine to fit their needs.',
    st: 'RPG (L86) and Platformer (L87) implement the same granular assist concept. Accessibility as a first-class feature — not an afterthought — is a universal game design principle across all paths.' },
  { file: 'lesson-shooter-88-crash-proofing.ts',
    bt: '**Only handling errors in the happy path.** Edge cases crash silently: empty pool on spawn, negative HP, out-of-bounds grid index. Validate at every system boundary — function entry, file load, pool access.',
    ei: 'Defensive programming in production games means: never crash, always degrade. If the pool is full, skip the spawn. If the save is corrupt, load defaults. The game continues, and the developer sees the warning.',
    st: 'RPG (L88) and Crawler crash-proof the same boundaries. Every path validates the same entry points: file I/O, user input, pool access, array bounds. The crash-proofing checklist is path-universal.' },
  { file: 'lesson-shooter-89-dead-code-cleanup.ts',
    bt: '**Commenting out dead code instead of deleting it.** Version control (git) preserves history. Commented-out code confuses future readers who wonder if it should be uncommented. Delete it — git log will have it if you need it.',
    ei: 'Martin Fowler: "Dead code is a liability, not an asset." Every line of commented-out code is a line a future developer must read, understand, and decide to keep or delete. Remove the decision burden.',
    st: 'RPG (L89) and Platformer (L89) perform the same cleanup. Code hygiene is universal: dead code, inconsistent naming, and copy-pasted logic are problems in every codebase regardless of genre.' },
  { file: 'lesson-shooter-90-milestone-public-beta.ts',
    bt: '**Releasing a beta without a test suite.** Manual testing cannot catch regressions across 90 lessons of accumulated code. Automated tests (RNG, collision, pool, save/load) catch what humans miss.',
    ei: 'Steam Early Access games ship with CI/CD pipelines that run automated test suites before each build reaches players. Your public beta milestone requires the same quality gate: tests pass, game does not crash.',
    st: 'RPG (L90), Platformer (L90), and Crawler all hit the same beta milestone. The criteria are identical: automated tests pass, no crashes in a 10-minute session, all systems functional. Genre is irrelevant to shipping quality.' },
  { file: 'lesson-shooter-91-build-id.ts',
    bt: '**Not including the build ID in crash reports.** When a player reports a bug, you need to know which exact build they are running. Embed the build ID in the window title and any diagnostic output.',
    ei: 'Every shipped game includes build metadata: version number, commit hash, build date. Steam, Xbox, and PlayStation all require version identification for certification. Your build ID meets this universal requirement.',
    st: 'RPG (L91) and Platformer (L91) embed the same build ID. Version tracking is a shipping requirement across all paths — the format is identical because the need is identical.' },
  { file: 'lesson-shooter-92-tests-rng.ts',
    bt: '**Testing RNG without fixing the seed.** If the seed changes each run, expected output changes too. Pin the seed, generate N values, compare against a known-good sequence stored in the test.',
    ei: 'Deterministic testing with fixed seeds is the standard for any system that uses randomness. Monte Carlo simulations, cryptographic tests, and game RNG tests all use the same approach: control the seed, control the output.',
    st: 'RPG (L92) and Crawler (L63) test RNG determinism the same way. Every path that implements seeded RNG must also verify it deterministically. The test pattern is identical across all paths.' },
  { file: 'lesson-shooter-93-tests-pools.ts',
    bt: '**Testing pool allocation without testing deallocation.** Allocate all slots, free them all, allocate again. If the second allocation fails, the free-list is broken. Always test the full alloc/free/reuse cycle.',
    ei: 'Memory allocator testing follows the alloc/free/stress pattern: allocate to capacity, free in random order, verify all slots are reclaimable. Your pool test follows the same methodology used for malloc implementations.',
    st: 'RPG and Crawler pool tests follow the same pattern. Platformer (L27) tests particle pool reuse. Pool lifecycle testing is universal because pool bugs (leaks, double-free, use-after-free) exist in every pool implementation.' },
  { file: 'lesson-shooter-94-tests-collision.ts',
    bt: '**Testing collision with overlapping rectangles only.** You need to test: overlapping (true), separated (false), touching edges (boundary case), and zero-size (degenerate). Four test cases cover the behavior space.',
    ei: 'Unit testing collision with known inputs and expected outputs is how physics engines verify correctness. Bullet Physics and Box2D both have extensive AABB test suites. Your four-case test follows the same methodology.',
    st: 'RPG tests combat formulas. Crawler tests spatial queries. Platformer (L93) tests grid collision. Every path tests its core collision/interaction system with deterministic inputs and expected outputs.' },
  { file: 'lesson-shooter-95-gate-c-zero-warnings.ts',
    bt: '**Suppressing warnings with casts instead of fixing the underlying issue.** A (int) cast on a size_t silences the warning but the truncation bug remains. Fix the type mismatch at the source, not at the symptom.',
    ei: 'Google, Mozilla, and game studios compile with -Wall -Werror. Warnings are treated as errors because they frequently indicate real bugs: unused variables, sign conversion, implicit narrowing.',
    st: 'RPG (L95), Platformer (L95), and Crawler all hit the same zero-warnings gate. Clean compilation is the universal quality bar — every path must pass before shipping.' },
  { file: 'lesson-shooter-96-readme-quickstart.ts',
    bt: '**Writing build instructions that only work on your machine.** Test the README on a clean environment (or have someone else follow the steps). If step 3 fails because of an unmentioned dependency, the README is incomplete.',
    ei: 'Open-source projects succeed or fail based on README quality. A "clone, build, run" sequence that works on the first try drives adoption. Your quickstart should get a new developer from zero to running game in under 5 minutes.',
    st: 'RPG (L96), Platformer (L96), and Crawler create READMEs. The structure is identical: project description, build instructions, controls, architecture overview. Documentation is a universal shipping requirement.' },
  { file: 'lesson-shooter-97-screenshot-capture.ts',
    bt: '**Capturing screenshots with debug overlays visible.** Profiling timers, collision boxes, and pool stats are developer tools. Portfolio screenshots should show clean gameplay. Disable debug rendering before capturing.',
    ei: 'Steam store pages require specific screenshot formats and content quality. Screenshots are marketing assets — they represent the game to potential players. Clean, well-composed screenshots are a shipping requirement.',
    st: 'RPG (L97), Platformer (L97), and Crawler produce clean gameplay screenshots. Visual artifacts for portfolio presentation are a universal deliverable — the game and the screenshots ship together.' },
  { file: 'lesson-shooter-98-final-content-pass.ts',
    bt: '**Polishing mechanics while leaving placeholder text.** "Enemy 1," "Wave N," and "Score: %d" are not player-facing strings. Review every DrawText call and replace debug formatting with polished presentation.',
    ei: 'QA teams flag placeholder text as a shipping blocker. Nintendo Treehouse reviews every player-facing string. Your content pass follows the same standard: every string the player sees must be intentional and polished.',
    st: 'RPG (L98), Platformer (L98), and Crawler perform the same content pass. Consistent naming, clear messaging, no placeholder text — the checklist is identical across all paths.' },
  { file: 'lesson-shooter-99-release-checklist.ts',
    bt: '**Skipping checklist items because they seem minor.** The one you skip is the one that causes a day-one bug. Checklists exist because complex systems have too many items for memory alone. Follow every item.',
    ei: 'NASA uses pre-launch checklists. Surgeons use pre-operation checklists. Game studios use release checklists. The pattern is universal: complex systems require systematic verification because humans forget under pressure.',
    st: 'RPG (L99), Platformer (L99), and Crawler use the same release checklist pattern. The items differ slightly by genre, but the discipline is identical: systematic verification before shipping.' },
  { file: 'lesson-shooter-100-ship-export-ready.ts',
    bt: '**Shipping without testing on a clean machine.** "Works on my machine" is not shipping evidence. Build from a clean checkout, run on a machine without your dev environment, verify the game starts and plays correctly.',
    ei: 'Valve tests every Steam release on standardized hardware profiles. The clean-room build test is the final quality gate. Your export-ready test follows the same principle: verify the build works outside your dev environment.',
    st: 'All four paths converge at Lesson 100: a standalone, shippable game ready for a portfolio. The final export is the culmination of 100 lessons of engineering discipline. Genre differences vanish at the shipping gate.' },
];

function findPart1InstructionsEnd(content) {
  const part1Idx = content.indexOf('part1:');
  if (part1Idx === -1) return -1;
  const marker = 'instructions: `';
  const instrStart = content.indexOf(marker, part1Idx);
  if (instrStart === -1) return -1;
  const openTick = instrStart + marker.length;
  let closeTick = openTick;
  while (closeTick < content.length) {
    if (content[closeTick] === '`' && content[closeTick - 1] !== '\\') break;
    closeTick++;
  }
  return closeTick;
}

let modified = 0, skipped = 0, errors = 0;
for (const lesson of lessons) {
  const filePath = path.join(dir, lesson.file);
  if (!fs.existsSync(filePath)) { console.log('ERROR (not found): ' + lesson.file); errors++; continue; }
  let content = fs.readFileSync(filePath, 'utf8');
  const insertPos = findPart1InstructionsEnd(content);
  if (insertPos === -1) { console.log('ERROR (no part1 instructions): ' + lesson.file); errors++; continue; }
  const part1Start = content.indexOf('part1:');
  const existing = content.substring(part1Start, insertPos);
  const hasBT = /beginner trap|common mistake/i.test(existing);
  const hasEI = /elite insight|pro insight/i.test(existing);
  const hasST = /systems thinking|cross-path/i.test(existing);
  let sections = '';
  if (!hasBT && lesson.bt) sections += '\n\n## Beginner Trap\n' + lesson.bt;
  if (!hasEI && lesson.ei) sections += '\n\n## Elite Insight\n' + lesson.ei;
  if (!hasST && lesson.st) sections += '\n\n## Systems Thinking Connection\n' + lesson.st;
  if (sections === '') { console.log('SKIP (all present): ' + lesson.file); skipped++; continue; }
  content = content.substring(0, insertPos) + sections + content.substring(insertPos);
  fs.writeFileSync(filePath, content, 'utf8');
  modified++;
  const part1Section = content.substring(content.indexOf('part1:'), content.indexOf('part2:'));
  const instrBackticks = (part1Section.match(/(?<!\\)`/g) || []).length;
  if (instrBackticks % 2 !== 0) console.log('WARNING (odd backticks): ' + lesson.file);
  else console.log('OK: ' + lesson.file);
}
console.log('\n=== SUMMARY ===');
console.log('Modified: ' + modified + '  Skipped: ' + skipped + '  Errors: ' + errors + '  Total: ' + lessons.length);
